package id.my.samastria.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.webkit.*;import android.content.*;import android.content.SharedPreferences;import android.text.InputType;import android.net.Uri;
public class MainActivity extends Activity {
 WebView web;FrameLayout root,offline;ProgressBar bar;float down;boolean gateShown=false;
 public void onCreate(Bundle b){super.onCreate(b);root=new FrameLayout(this);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);CookieManager.getInstance().setAcceptCookie(true);root.addView(web);bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);root.addView(bar,new FrameLayout.LayoutParams(-1,8,Gravity.TOP));
 offline=new FrameLayout(this);offline.setBackgroundColor(-1);TextView msg=new TextView(this);msg.setText("Koneksi internet bermasalah.\nPeriksa koneksi lalu coba lagi.");msg.setTextSize(18);msg.setGravity(Gravity.CENTER);FrameLayout.LayoutParams mp=new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER);mp.setMargins(24,24,24,100);offline.addView(msg,mp);Button retry=new Button(this);retry.setText("Coba Lagi");retry.setOnClickListener(v->{offline.setVisibility(8);web.reload();});FrameLayout.LayoutParams rp=new FrameLayout.LayoutParams(-2,-2,Gravity.CENTER);rp.topMargin=100;offline.addView(retry,rp);offline.setVisibility(8);root.addView(offline);TextView splash=new TextView(this);splash.setText("SAMASTRIA ADMIN");splash.setTextColor(-1);splash.setTextSize(22);splash.setGravity(Gravity.CENTER);splash.setBackgroundColor(Color.rgb(20,115,75));root.addView(splash);setContentView(root);
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("http".equals(u.getScheme())||"https".equals(u.getScheme()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){}return true;}public void onPageFinished(WebView v,String u){offline.setVisibility(8);bar.setVisibility(8);}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()){offline.setVisibility(0);bar.setVisibility(8);}}});web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int p){bar.setProgress(p);bar.setVisibility(p>=100?8:0);}});web.setOnTouchListener((v,e)->{if(e.getAction()==0)down=e.getY();if(e.getAction()==1&&web.getScrollY()==0&&e.getY()-down>120){web.reload();return true;}return false;});if(b!=null)web.restoreState(b);else root.postDelayed(()->{root.removeView(splash);},1000);
 }
 protected void onResume(){super.onResume();if(!gateShown){gateShown=true;pinGate();}}
 void pinGate(){SharedPreferences p=getSharedPreferences("admin_lock",0);String stored=p.getString("pin",null);EditText field=new EditText(this);field.setInputType(2|16);field.setHint(stored==null?"Buat PIN 4 angka":"Masukkan PIN Admin");AlertDialog d=new AlertDialog.Builder(this).setTitle(stored==null?"Pengamanan Admin":"Kunci Admin").setView(field).setCancelable(false).setPositiveButton(stored==null?"Simpan":"Buka",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String val=field.getText().toString();if(val.length()!=4){field.setError("PIN wajib 4 angka");return;}if(stored==null){p.edit().putString("pin",val).apply();d.dismiss();web.loadUrl("https://samastria.my.id/admin.html");}else if(stored.equals(val)){d.dismiss();if(web.getUrl()==null)web.loadUrl("https://samastria.my.id/admin.html");}else field.setError("PIN salah");}));d.show();}
 public boolean onCreateOptionsMenu(Menu m){m.add("Bagikan Samastria");m.add("Versi aplikasi");return true;}public boolean onOptionsItemSelected(MenuItem i){if(i.getTitle().equals("Bagikan Samastria")){Intent s=new Intent(Intent.ACTION_SEND);s.setType("text/plain");s.putExtra(Intent.EXTRA_TEXT,"Samastria: https://samastria.my.id/");startActivity(Intent.createChooser(s,"Bagikan"));return true;}if(i.getTitle().equals("Versi aplikasi")){Toast.makeText(this,"Samastria Admin versi 1.1",1).show();return true;}return false;}
 public void onSaveInstanceState(Bundle b){web.saveState(b);super.onSaveInstanceState(b);}public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("Keluar dari Admin Samastria?").setNegativeButton("Batal",null).setPositiveButton("Keluar",(d,w)->finish()).show();}protected void onDestroy(){web.destroy();super.onDestroy();}
}